namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.",
            Ratings = new List<int> { 5, 4, 5, 4 }
        },
        new Recipe
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast, Yogurt, Garam masala, Cumin, Tomato sauce, Heavy cream, Garlic, Ginger, Onion",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or pan-fry chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 min.\n5. Stir in cream and cooked chicken.\n6. Serve over basmati rice.",
            Ratings = new List<int> { 5, 5, 4 }
        },
        new Recipe
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Taco seasoning",
            Steps = "1. Brown ground beef in skillet.\n2. Add taco seasoning and water, simmer 5 min.\n3. Warm taco shells in oven.\n4. Assemble tacos with meat and toppings.\n5. Serve with salsa and lime wedges.",
            Ratings = new List<int> { 4, 4, 3, 5 }
        },
        new Recipe
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Pancetta, Eggs, Parmesan cheese, Black pepper, Salt",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Fry pancetta until crispy.\n3. Whisk eggs with grated Parmesan and pepper.\n4. Toss hot pasta with pancetta.\n5. Remove from heat, stir in egg mixture quickly.\n6. Serve immediately with extra Parmesan.",
            Ratings = new List<int> { 5, 5, 5 }
        },
        new Recipe
        {
            Id = 5, Title = "Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Lime, Fish sauce, Tamarind paste, Sugar",
            Steps = "1. Soak rice noodles in warm water 30 min.\n2. Make sauce: mix tamarind, fish sauce, and sugar.\n3. Stir-fry shrimp, set aside.\n4. Scramble eggs in wok.\n5. Add noodles and sauce, toss until coated.\n6. Add shrimp, bean sprouts, top with peanuts and lime.",
            Ratings = new List<int> { 4, 5, 4, 4 }
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt",
            Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Dice onion, tomato, jalapeño, and cilantro.\n4. Mix everything together.\n5. Add lime juice and salt to taste.\n6. Serve immediately with tortilla chips.",
            Ratings = new List<int> { 5, 4, 5 }
        },
        new Recipe
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Ingredients = "Coconut milk, Green curry paste, Chicken thigh, Bamboo shoots, Thai basil, Fish sauce, Sugar, Eggplant",
            Steps = "1. Heat coconut cream in pan until oil separates.\n2. Fry curry paste 2 minutes.\n3. Add chicken, cook until sealed.\n4. Pour in remaining coconut milk.\n5. Add vegetables, simmer 15 min.\n6. Season with fish sauce and sugar, garnish with basil.",
            Ratings = new List<int> { 4, 5 }
        },
        new Recipe
        {
            Id = 8, Title = "Butter Chicken", Category = "Indian",
            Ingredients = "Chicken thigh, Butter, Tomato puree, Cream, Garam masala, Fenugreek leaves, Garlic, Ginger, Chili powder",
            Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or bake chicken until done.\n3. Make sauce: cook garlic, ginger in butter.\n4. Add tomato puree, simmer 20 min.\n5. Stir in cream and fenugreek.\n6. Add chicken to sauce, serve with naan.",
            Ratings = new List<int> { 5, 5, 4, 5 }
        }
    };

    private int _nextId = 9;

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe != null && stars >= 1 && stars <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps
        });
    }
}

