arguments.file_text:
@using RecipeCommunity.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    <span class="me-2 text-muted small">
        @if (TotalRatings > 0)
        {
            <span>@AverageRating.ToString("0.0") avg (@TotalRatings ratings)</span>
        }
        else
        {
            <span>No ratings yet</span>
        }
    </span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "selected" : "") @(star <= _hoverRating ? "hover" : "")"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              @onclick="() => SubmitRating(star)"
              role="button"
              title="Rate @star stars">
            ★
        </span>
    }
    @if (_submitted)
    {
        <span class="ms-2 text-success small">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.5rem;
        color: #ccc;
        cursor: pointer;
        transition: color 0.15s;
    }
    .star-rating .star.selected {
        color: #ffc107;
    }
    .star-rating .star.hover {
        color: #ffdb4d;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _selectedRating;
    private int _hoverRating;
    private bool _submitted;
    private double AverageRating;
    private int TotalRatings;

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe != null)
        {
            AverageRating = recipe.AverageRating;
            TotalRatings = recipe.Ratings.Count;
        }
    }

    private void SubmitRating(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        _submitted = true;
        LoadRating();
    }
}

@page "/"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Recipe Community - Home</PageTitle>

<div class="container">
    <div class="text-center my-4">
        <h1>🍳 Recipe Community</h1>
        <p class="lead">Discover and share delicious recipes from around the world</p>
    </div>

    <div class="row">
        @foreach (var category in RecipeService.GetCategories())
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body text-center">
                        <h3 class="card-title">@GetCategoryEmoji(category) @category</h3>
                        <p class="card-text text-muted">
                            @RecipeService.GetRecipesByCategory(category).Count recipes
                        </p>
                        <a href="/category/@category" class="btn btn-outline-primary">Browse Recipes</a>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="text-center mt-4">
        <a href="/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
    </div>
</div>

@code {
    private string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h2>@CategoryName Recipes</h2>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted small">
                                @if (recipe.AverageRating > 0)
                                {
                                    <span>⭐ @recipe.AverageRating.ToString("0.0") (@recipe.Ratings.Count ratings)</span>
                                }
                                else
                                {
                                    <span>No ratings yet</span>
                                }
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<RecipeCommunity.Models.Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe != null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe == null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h2>@Recipe.Title</h2>
        <span class="badge bg-secondary mb-3">@Recipe.Category</span>

        <div class="mb-4">
            <h5>Rate this recipe:</h5>
            <StarRating RecipeId="@Recipe.Id" />
        </div>

        <div class="card mb-4">
            <div class="card-header">
                <h5 class="mb-0">🥘 Ingredients</h5>
            </div>
            <div class="card-body">
                <ul class="mb-0">
                    @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                    {
                        <li>@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-header">
                <h5 class="mb-0">📋 Steps</h5>
            </div>
            <div class="card-body">
                @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <p>@step</p>
                }
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipe(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h2>📝 Submit a Recipe</h2>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h5>Recipe submitted successfully! 🎉</h5>
            <p>Your recipe has been added to the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="_submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="_submission.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_submission.Category">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Thai">Thai</option>
                    <option value="American">American</option>
                    <option value="French">French</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_submission.Ingredients"
                    placeholder="One ingredient per line or comma-separated" />
                <div class="form-text">Separate ingredients with commas or new lines.</div>
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Preparation Steps</label>
